<?php
$uid = (int)$u['id'];
handle('tok_create', function () use ($uid) { Auth::verifyPin($uid, (string)($_POST['pin'] ?? '')); $t = Tokens::create($uid, (int)$_POST['merchant'], (string)$_POST['per'], (string)$_POST['monthly']); $_SESSION['new_token'] = $t; return 'Token created. Copy it now: it is shown only once.'; });
handle('tok_status', function () use ($uid) { Tokens::setStatus($uid, (int)$_POST['id'], in_array($_POST['to'], ['active', 'paused', 'cancelled'], true) ? $_POST['to'] : 'paused'); return 'Token updated.'; });
echo page_head('Virtual tokens', 'Merchant-specific payment tokens you can pause or cancel. A merchant can only charge its own token, within the limits you set.');
echo '<div class="alert info">SIMULATED: tokens work only inside Auvryon. They are not real card numbers. This is how ghost charges (unexpected recurring charges) are blocked: pause or cancel the token and the merchant is declined.</div>';
if (!empty($_SESSION['new_token'])) { echo '<div class="alert ok" style="display:block"><strong>Your new token (shown once):</strong><div class="mono" id="newtok" style="margin:6px 0;word-break:break-all">' . e($_SESSION['new_token']) . '</div><button class="btn secondary sm" type="button" data-copy="newtok">Copy</button></div>'; unset($_SESSION['new_token']); }
$ts = rows('SELECT t.*, m.business_name, (SELECT COALESCE(SUM(amount),0) FROM token_charges c WHERE c.token_id=t.id AND c.status="approved" AND c.created_at>=DATE_FORMAT(CURDATE(),"%Y-%m-01")) used FROM virtual_tokens t JOIN merchants m ON m.id=t.merchant_id WHERE t.user_id=? ORDER BY t.id DESC', [$uid]); $rows = [];
foreach ($ts as $t) { $b = ''; if ($t['status'] !== 'cancelled') { $b = form_start('tok_status', 'class="inline"') . '<input type="hidden" name="id" value="' . (int)$t['id'] . '"><input type="hidden" name="to" value="' . ($t['status'] === 'active' ? 'paused' : 'active') . '">' . btn($t['status'] === 'active' ? 'Pause' : 'Resume', 'secondary sm') . '</form> ' . form_start('tok_status', 'class="inline"') . '<input type="hidden" name="id" value="' . (int)$t['id'] . '"><input type="hidden" name="to" value="cancelled">' . btn('Cancel', 'secondary sm', 'submit', 'onclick="return confirm(\'Cancel permanently?\')"') . '</form>'; }
  $rows[] = [e($t['business_name']) . '<div class="hint mono">avt_...' . e($t['token_last4']) . '</div>', mny($t['per_charge_limit']) . ' / charge<div class="hint">' . mny($t['used']) . ' of ' . mny($t['monthly_limit']) . ' this month</div>', badge($t['status']), $b]; }
$mer = []; foreach (rows("SELECT id, business_name FROM merchants WHERE status='active' ORDER BY business_name") as $m) $mer[$m['id']] = $m['business_name'];
$log = rows('SELECT c.*, m.business_name, t.token_last4 FROM token_charges c JOIN virtual_tokens t ON t.id=c.token_id JOIN merchants m ON m.id=t.merchant_id WHERE t.user_id=? ORDER BY c.id DESC LIMIT 10', [$uid]); $lr = [];
foreach ($log as $c) $lr[] = [e(fdate($c['created_at'])), e($c['business_name']), mny($c['amount']), badge($c['status']), e($c['reason'])];
echo '<div class="grid g-main"><div class="grid">' . card('Your tokens', tbl(['Merchant', 'Limits', 'Status', ''], $rows, 'No tokens yet.')) . card('Charge attempts', tbl(['When', 'Merchant', ['Amount', 'num'], 'Result', 'Reason'], $lr, 'No charge attempts yet.')) . '</div>' . card('Create token', form_start('tok_create') . select('Merchant', 'merchant', $mer) . field('Max per charge (BDT)', 'per', 'text', '500', 'required inputmode="decimal"') . field('Max per month (BDT)', 'monthly', 'text', '2000', 'required inputmode="decimal"') . pin_field() . btn('Create token') . '</form>') . '</div>';
